def minColours(n, edges):
    if not edges:
        return 1
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        parent[find(a)] = find(b)
    nodes = {}
    for v in range(n):
        root = find(v)
        nodes[root] = nodes.get(root, 0) + 1
    links = {}
    for a, b in edges:
        root = find(a)
        links[root] = links.get(root, 0) + 1
    for root, k in links.items():
        if k == nodes[root] and k % 2 == 1:
            return 3
    return 2
